import React, { useState, useEffect } from 'react';
import './Dashboard.css';
import VerifierPin from './VerifierPin';

function Dashboard({ allerVers, utilisateur }) {
  const [donnees, setDonnees] = useState(null);
  const [chargement, setChargement] = useState(true);
  const [pinVerifie, setPinVerifie] = useState(false);

  useEffect(() => {
    if (!utilisateur || utilisateur.role !== 'artiste') {
      allerVers('accueil');
      return;
    }

    fetch(`/api/dashboard/${utilisateur.id}`)
      .then(res => res.json())
      .then(data => {
        setDonnees(data);
        setChargement(false);
      })
      .catch(() => setChargement(false));
  }, [utilisateur]);

  if (chargement) return (
    <div className="dashboard-page">
      <div className="chargement">Chargement du dashboard...</div>
    </div>
  );

  if (!pinVerifie) {
    return (
      <VerifierPin
        utilisateur={utilisateur}
        titre="Accès Dashboard"
        onSuccess={() => setPinVerifie(true)}
        onCancel={() => allerVers('accueil')}
      />
    );
  }

  return (
    <div className="dashboard-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>🎵 Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('catalogue')}>Catalogue</a>
          <a href="#" className="actif">Mon Dashboard</a>
        </nav>
        <div className="auth-buttons">
          <span className="user-prenom">👋 {utilisateur?.prenom}</span>
          <button className="btn-publier" onClick={() => allerVers('upload')}>
            + Publier
          </button>
          <button className="btn-login" onClick={() => {
            localStorage.removeItem('token');
            localStorage.removeItem('utilisateur');
            allerVers('accueil');
          }}>Déconnexion</button>
        </div>
      </header>

      <div className="dashboard-contenu">
        <h1 className="dashboard-titre">🎛️ Mon Dashboard</h1>
        <p className="dashboard-sous-titre">Bienvenue, {utilisateur?.prenom} !</p>

        <div className="stats-grille">
          <div className="stat-carte">
            <div className="stat-icone">🎵</div>
            <div className="stat-valeur">{donnees?.musiques?.length || 0}</div>
            <div className="stat-label">Musiques publiées</div>
          </div>
          <div className="stat-carte">
            <div className="stat-icone">🛒</div>
            <div className="stat-valeur">{donnees?.totaux?.total_ventes || 0}</div>
            <div className="stat-label">Total ventes</div>
          </div>
          <div className="stat-carte revenus">
            <div className="stat-icone">💰</div>
            <div className="stat-valeur">{donnees?.totaux?.total_revenus || 0} FCFA</div>
            <div className="stat-label">Mes revenus</div>
          </div>
          <div className="stat-carte commission">
            <div className="stat-icone">📊</div>
            <div className="stat-valeur">{donnees?.totaux?.total_commissions || 0} FCFA</div>
            <div className="stat-label">Commissions Varim</div>
          </div>
        </div>

        <div className="dashboard-section">
          <h2>🎵 Mes musiques</h2>
          {donnees?.musiques?.length === 0 ? (
            <div className="vide">
              <p>Vous n'avez pas encore publié de musique.</p>
              <button className="btn-publier-grand" onClick={() => allerVers('upload')}>
                + Publier ma première musique
              </button>
            </div>
          ) : (
            <div className="musiques-liste">
              {donnees?.musiques?.map(musique => (
                <div key={musique.id} className="musique-ligne">
                  <div className="musique-pochette">
                    {musique.pochette_url ? (
                      <img src={musique.pochette_url} alt={musique.titre} />
                    ) : (
                      <div className="pochette-defaut">
                        {musique.type === 'album' ? '💿' : '🎵'}
                      </div>
                    )}
                  </div>
                  <div className="musique-info">
                    <h3>{musique.titre}</h3>
                    <p>{musique.type === 'album' ? '💿 Album' : '🎵 Single'} — {musique.genre}</p>
                    <p className="musique-prix">{musique.prix} FCFA</p>
                  </div>
                  <div className="musique-stats">
                    <div className="mini-stat">
                      <span className="mini-val">{musique.nb_ventes_reel}</span>
                      <span className="mini-label">ventes</span>
                    </div>
                    <div className="mini-stat revenus">
                      <span className="mini-val">{musique.revenus_total} FCFA</span>
                      <span className="mini-label">revenus</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="dashboard-section">
          <h2>🔔 Dernières ventes</h2>
          {donnees?.dernieresVentes?.length === 0 ? (
            <div className="vide">Aucune vente pour l'instant.</div>
          ) : (
            <div className="ventes-liste">
              {donnees?.dernieresVentes?.map(vente => (
                <div key={vente.id} className="vente-ligne">
                  <div className="vente-info">
                    <span className="vente-titre">{vente.titre}</span>
                    <span className="vente-acheteur">acheté par {vente.acheteur_prenom}</span>
                  </div>
                  <div className="vente-montant">
                    <span className="vente-revenu">+{vente.revenu_artiste} FCFA</span>
                    <span className="vente-date">
                      {new Date(vente.date_achat).toLocaleDateString('fr-FR')}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
